declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)($_SESSION['role']??'');$allowed=['hr','admin','director','sub_director','headteacher'];if(!in_array($role,$allowed,true)){http_response_code(403);exit('Your role cannot view staff workloads.');}$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([(int)$_SESSION['user_id']]);$schools=$q->fetchAll();if(!$schools){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$schools[0]['id']);$ids=array_map('intval',array_column($schools,'id'));if(!in_array($school,$ids,true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='';foreach($schools as $s)if((int)$s['id']===$school)$schoolName=$s['name'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff workload · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/staff-workload.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">People <span>/</span> Staff workload</div></header><div class="page-content" data-staff-workload data-api="api/staff_workload.php" data-school="<?=$school?>"><section class="welcome-row"><div><div class="eyebrow"><?=e($schoolName)?></div><h1>Staff workload</h1><p class="muted">Based on active teacher assignments, published weekly timetable periods and lesson plans awaiting review. Minutes reflect scheduled periods only.</p></div><?php if(count($schools)>1):?><form method="get"><label for="workload-school">School</label><select id="workload-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><div data-workload-status class="notice" role="status" aria-live="polite" hidden></div><section class="content-section"><div class="section-heading"><div><div class="eyebrow">TEACHING ACTIVITY</div><h2>Active staff overview</h2></div><button class="button" type="button" data-workload-refresh>Refresh</button></div><div class="table-wrap" data-workload-table><p class="muted">Loading staff workload…</p></div></section><footer class="page-footer">ShuleLite · Staff workload</footer></div></main></div></div></body></html>